def shortest_path(graph, source, target):

    def bfs(start, target):
        if start == target:
            return [(start, 0)]
        queue = [(start, 0)]
        visited = set()
        while queue:
            current_node, distance = queue.pop(0)
            if current_node in visited:
                continue
            visited.add(current_node)
            for neighbor, weight in graph.get(current_node, []):
                if neighbor == target:
                    return [(neighbor, distance + weight)]
                queue.append((neighbor, distance + weight))
        return None

    def fallback_path(start, target):
        visited = set()
        stack = [(start, [start])]
        while stack:
            current_node, path = stack.pop()
            if current_node in visited:
                continue
            visited.add(current_node)
            if current_node == target:
                return path
            for neighbor in graph.get(current_node, []):
                stack.append((neighbor[0], path + [neighbor[0]]))
        return None
    if target in graph.get(source, []):
        return (1, [source, target])
    path = bfs(source, target)
    if path:
        return (len(path) - 1, path)
    fallback_path_result = fallback_path(source, target)
    if fallback_path_result is None:
        return (float('inf'), None)
    distance = len(fallback_path_result) - 1
    return (distance, fallback_path_result)
