function shortest_path(graph, source, target) {
    // Set of all nodes in the graph
    const all_nodes = new Set(Object.keys(graph));

    // Array to keep track of visited nodes
    const visited = new Set();

    // Queue for BFS, structured as [distance, node, path]
    const queue = [[0, source, [source]]];
    visited.add(source);

    // Perform BFS
    while (queue.length > 0) {
        const [distance, curr_node, path] = queue.shift();

        // If we have reached the target, return the path
        if (curr_node === target) {
            return [distance, path];
        }

        // Explore neighbors
        for (const [neighbor, weight] of graph[curr_node]) {
            if (!visited.has(neighbor)) {
                visited.add(neighbor);
                const new_path = [...path, neighbor];
                queue.push([distance + weight, neighbor, new_path]);
            }
        }
    }

    // If we exit the loop, it means target is unreachable
    return [Number.POSITIVE_INFINITY, null];
}

